Stan source code for the Zero-inflated Spatial Poisson regression model

functions { // Using r e d u c e sum f o r w i t h i n −c h a i n p a r a l l e l p r o c e s s i n g .
// f u n c t i o n f o r c a l c u l a t i n g t h e l o g −l i k e l i h o o d
r e a l p a r t i a l s u m l p m f ( int [ ] y s l i c e ,
int s t a r t , int end ,
matrix X t o t a l ,
vector l o g d u r a t i o n ,
vector b e t a t o t a l , r e a l t h e t a z e r o i n f l a t i o n ) {
int Nloc = end − s t a r t ;
real l o c a l t a r g e t = 0 ;
// two c a s e s f o r c a l c u l a t i o n r e f l e c t i n g z er o −i n f l a t i o n
for ( n in 1 : Nloc +1) {
int i n d = s t a r t + n − 1 ;
i f ( y s l i c e [ n ] == 0 ) {
l o c a l t a r g e t +=
log sum exp ( bernoulli lpmf ( 1 | t h e t a z e r o i n f l a t i o n ) ,
bernoulli lpmf ( 0 | t h e t a z e r o i n f l a t i o n )
+ p o i s s o n l o g g l m l p m f ( y s l i c e [ n ] | X t o t a l [ i n d : ind , : ] ,
l o g d u r a t i o n [ ind : ind ] , b e t a t o t a l )
);
} else {
l o c a l t a r g e t +=
bernoulli lpmf ( 0 | t h e t a z e r o i n f l a t i o n )
+ p o i s s o n l o g g l m l p m f ( y s l i c e [ n ] | X t o t a l [ i n d : ind , : ] ,
ogduration [ ind : ind ] , b e t a t o t a l

model { // P r i o r p a r t o f Bayesian i n f e r e n c e
b e t a t r a c t ˜ normal ( 0 , 1 ) ;
b e t a c a t e g o r y ˜ normal ( 0 , 2∗ inv ( sqrt ( 1 − inv ( N c a t e g o r y ) ) ) ) ;
beta ˜ normal ( 0 , 1 ) ;
i n t e r c e p t ˜ normal ( 0 , 5 ) ;
68

 // Use r e d u c e sum t o c a l c u l a t e t h e t a r g e t l i k e l i h o o d
int g r a i n s i z e = 1 ;
target += reduce sum (
partial sum lpmf , y , grainsize , X total ,
logduration , beta total , t h e t a z e r o i n f l a t i o n
);
// add a d j a c e n c y p r i o r s t o b e t a t r a c t
target += −5 ∗ d o t s e l f ( b e t a t r a c t [ node1 ] − b e t a t r a c t [ node2 ] ) ;
}
